import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { z } from 'zod';
import { hash, hex, rpcTransaction } from '../../src/model.js';
import { ownedNode } from './owned-node.js';

/** All keys and coins are generated by the newly owned, peer-disabled regtest node. */
export async function ownedScenario(binary: string) {
  const node = await ownedNode(binary);
  try {
    await node.call('createwallet', ['blaze-acceptance']);
    const wallet = (method: string, params: unknown[] = []) => node.call(method, params, 'blaze-acceptance');
    const address = z.string().parse(await wallet('getnewaddress'));
    await node.call('generatetoaddress', [101, address]);
    const category = hash.parse(await wallet('sendtoaddress', [address, 1]));
    await node.call('generatetoaddress', [1, address]);
    const parent = rpcTransaction.parse(await node.call('getrawtransaction', [category, true]));
    const previous = parent.vout.find(output => output.n === 0);
    assert.ok(previous);
    const recipients = await Promise.all(Array.from({ length: 4 }, async () => z.string().parse(await wallet('getnewaddress'))));
    const [holder, mint, child, change] = recipients;
    assert.ok(holder && mint && child && change);
    const registry = JSON.stringify({ version: { major: 0, minor: 1, patch: 0 },
      latestRevision: '2026-11-15T00:00:00.000Z', registryIdentity: { name: 'Blaze owned regtest' } });
    const contentHash = createHash('sha256').update(registry).digest('hex');
    const changeValue = (BigInt(previous.value.toFixed(8).replace('.', '')) - 31000n).toString();
    const changeBch = `${changeValue.slice(0, -8) || '0'}.${changeValue.padStart(8, '0').slice(-8)}`;
    const raw = hex.parse(await node.call('createrawtransaction', [[{ txid: category, vout: 0 }], [
      { [holder]: { amount: '0.00010000', tokenData: { category, amount: '9007199254740993', nft: { capability: 'mutable', commitment: '' } } } },
      { [mint]: { amount: '0.00010000', tokenData: { category, amount: '0', nft: { capability: 'minting', commitment: '' } } } },
      { [child]: { amount: '0.00010000', tokenData: { category, amount: '7', nft: { capability: 'none', commitment: 'abcd' } } } },
      { [change]: changeBch }, { data: ['42434d52', contentHash, Buffer.from('example.invalid').toString('hex')] },
    ]]));
    const signed = z.object({ hex, complete: z.literal(true) }).parse(await wallet('signrawtransactionwithwallet', [raw]));
    const decoded = rpcTransaction.parse(await node.call('decoderawtransaction', [signed.hex]));
    const acceptance = z.array(z.object({ allowed: z.boolean(), 'reject-reason': z.string().optional() }))
      .parse(await node.call('testmempoolaccept', [[signed.hex]]));
    assert.equal(acceptance[0]?.allowed, true, JSON.stringify(acceptance));
    // Broadcast exactly once. If the call fails, callers must reconcile this precomputed txid.
    assert.equal(hash.parse(await node.call('sendrawtransaction', [signed.hex])), decoded.txid);
    await node.call('generatetoaddress', [1, address]);
    const script = z.object({ scriptPubKey: hex }).parse(await node.call('validateaddress', [holder])).scriptPubKey;
    return { ...node, wallet, address, holder, mint, child, change, script, category, genesisTxid: decoded.txid,
      registry, contentHash, genesisInputSatoshis: BigInt(previous.value.toFixed(8).replace('.', '')).toString(), signedGenesis: signed.hex };
  } catch (cause) { await node.close(); throw cause; }
}
